// spec: .qa/e2e/specs/admin-content.md 1.1 · seed: tests/seed.admin.spec.ts · тикет #686cecdc (AC 1–7)
// Только просмотр: «כל התוכן» → «סוג» → каждый тип; данные не меняются → @prod-safe, без @data. Админка — только десктоп.
import { test, expect } from '@playwright/test';
import { adminAs, closeAdmin, contentQueue, openContent } from '../moderation-menu/mod-helpers';

// пункт меню «סוג» → значение type= в адресе → подпись типа в строке списка
const TYPES = [
  { item: 'פוסטים', label: 'פוסט' },
  { item: 'תגובות', label: 'תגובה' },
  { item: 'סטוריז', label: 'סטורי' },
  { item: "צ'אט קהילתי", label: 'הודעה בקהילה' },
  { item: 'הודעות בחדרים', label: 'הודעה בחדר' },
  { item: 'תמונות פרופיל', label: 'תמונת פרופיל' },
];

test.describe('מסך ניהול תוכן — просмотр', () => {
  test('«כל התוכן» → фильтр «סוג»: посты, комментарии, сторис, общий чат, комнаты, фото профиля — в списке только выбранный тип @desktop @prod-safe (#686cecdc)', async ({ browser }) => {
    test.setTimeout(120_000);
    const page = await adminAs(browser);
    try {
      await openContent(page, '?tab=all');
      await expect(page.getByRole('tab', { name: 'כל התוכן' })).toHaveAttribute('aria-selected', 'true');
      const typeBtn = page.getByRole('button', { name: /^סוג:/ });
      await expect(typeBtn).toHaveText(/סוג: הכול/);

      // Меню «סוג»: все типы контента из AC 1–6 со счётчиками
      await typeBtn.click();
      const menu = page.getByRole('menu');
      for (const t of TYPES) await expect(menu.getByRole('menuitem', { name: new RegExp(`^${t.item}( \\d+)?$`) })).toBeVisible();
      await page.keyboard.press('Escape');

      for (const t of TYPES) {
        await typeBtn.click();
        const mi = page.getByRole('menu').getByRole('menuitem', { name: new RegExp(`^${t.item}( \\d+)?$`) });
        const count = Number(((await mi.textContent()) ?? '').match(/(\d+)\s*$/)?.[1] ?? '0');
        await mi.click();
        await expect(page).toHaveURL(/[?&]type=/);
        await expect(typeBtn).toHaveText(new RegExp(`סוג: ${t.item}`));
        const rows = contentQueue(page).getByRole('list').first().getByRole('link');
        if (count === 0) {
          await expect(contentQueue(page).getByText('לא נמצא תוכן תואם')).toBeVisible();
          continue;
        }
        await expect(rows.first()).toBeVisible();
        // каждая строка списка — выбранного типа (вторая строка карточки: «<тип> · <место>»)
        const metas = await rows.evaluateAll((links) => links.map((a) => a.querySelectorAll('p')[1]?.textContent?.trim() ?? ''));
        expect(metas.length, `строки типа «${t.item}»`).toBeGreaterThan(0);
        for (const m of metas) expect(m, `строка в фильтре «${t.item}»`).toMatch(new RegExp(`^${t.label}`));
      }
    } finally {
      await closeAdmin(page);
    }
  });
});
